39	/** A play-usable Profile from a server-side account profile (skin sanitized). */
40	function profileFromOnline(profile: OnlineProfile): Profile {
41	  return { id: profile.id, name: profile.name, skinId: isSkinId(profile.skinId) ? profile.skinId : DEFAULT_SKIN_ID, createdAt: 0 };
