44	/** Online worlds mount the same game subtree; the meta is a projection of the server row. */
45	function onlineWorldMeta(world: OnlineWorld, profileId: string): WorldMeta {
46	  return {
47	    id: `online:${world.id}`,
48	    profileId,
49	    name: world.name,
50	    seed: world.seed,
51	    worldType: world.worldType as WorldMeta["worldType"],
52	    gameMode: world.gameMode as WorldMeta["gameMode"],
53	    difficulty: world.difficulty as WorldMeta["difficulty"],
54	    hardcore: world.hardcore,
55	    worldgenVersion: world.worldgenVersion,
56	    createdAt: 0,
57	    lastPlayedAt: 0
58	  };
59	}
60	
61	/**
62	 * Remembers the world being played for this tab so a reload resumes it instead
63	 * of dropping back to the menu. sessionStorage (not localStorage) so a brand-new
64	 * tab still cold-starts at profile-select.
65	 */
66	const SESSION_KEY = "monecraft_active_session";
67	
68	function readSessionPointer(): { profileId: string; worldId: string } | null {
69	  try {
70	    const raw = sessionStorage.getItem(SESSION_KEY);
71	    if (!raw) return null;
