                      if (count !== null) setInvitesRevoked(world.id);
                    });
                  }}
                >
                  {invitesRevoked === world.id ? "Links revoked" : "Revoke links"}
                </button>
              </div>
            )}
          </li>
        ))}
      </ul>
    )}
    <button className="mc-button" data-testid="new-online-world" onClick={() => setCreatingOnline(true)}>
      New Online World
    </button>
  </section>
)}
