2	import { render, screen, waitFor } from "@testing-library/react";
3	import userEvent from "@testing-library/user-event";
4	
5	// The panel talks to better-auth over fetch; component tests swap the client
6	// module for a controllable fake so no network (or server) exists.
7	const fake = {
8	  user: null as null | { id: string; name: string; email: string; isAnonymous: boolean },
9	  signInAnonymousCalls: 0,
10	  signOutRejects: false
11	};
12	
13	void mock.module("@/lib/auth/client", () => ({
14	  authClient: () => ({
15	    signUp: { email: async () => ({ error: null }) },
16	    signIn: {
17	      email: async () => ({ error: null }),
18	      anonymous: async () => {
19	        fake.signInAnonymousCalls += 1;
20	        fake.user = { id: "guest-1", name: "Anonymous", email: "temp@x", isAnonymous: true };
21	        return { error: null };
22	      }
23	    },
24	    signOut: async () => {
25	      if (fake.signOutRejects) throw new Error("network down");
26	      fake.user = null;
27	      return { error: null };
28	    }
29	  }),
30	  onlineUsed: () => true,
31	  markOnlineUsed: () => {},
32	  currentUser: async () => fake.user,
33	  ensureSignedIn: async () => {
34	    if (!fake.user) {
35	      fake.signInAnonymousCalls += 1;
36	      fake.user = { id: "guest-1", name: "Anonymous", email: "temp@x", isAnonymous: true };
37	    }
38	    return fake.user;
39	  }
40	}));
41	
42	const { default: AccountPanel } = await import("./AccountPanel");
43	
44	describe("AccountPanel", () => {
45	  test("offline → guest → upgrade offer", async () => {
46	    fake.user = null;
47	    render(<AccountPanel />);
48	    await waitFor(() => expect(screen.getByText("Offline")).toBeTruthy());
49	
50	    await userEvent.click(screen.getByRole("button", { name: "Play online as guest" }));
51	    await waitFor(() => expect(screen.getByText("Playing as guest")).toBeTruthy());
52	    expect(fake.signInAnonymousCalls).toBe(1);
53	
54	    // A guest is offered the worlds-keeping upgrade, which opens the sign-up form.
55	    await userEvent.click(screen.getByRole("button", { name: "Keep my worlds — create account" }));
56	    expect(screen.getByText("Create account (keeps your worlds)")).toBeTruthy();
57	    expect(screen.getByText("Email")).toBeTruthy();
58	  });
59	
60	  test("a guest can sign out and return to the login screen", async () => {
61	    fake.user = null;
62	    render(<AccountPanel />);
63	    await waitFor(() => expect(screen.getByText("Offline")).toBeTruthy());
64	
65	    await userEvent.click(screen.getByRole("button", { name: "Play online as guest" }));
66	    await waitFor(() => expect(screen.getByText("Playing as guest")).toBeTruthy());
67	
68	    // A guest previously had no way back; sign out returns to the offline/login state.
69	    await userEvent.click(screen.getByRole("button", { name: "Sign out" }));
70	    await waitFor(() => expect(screen.getByText("Offline")).toBeTruthy());
71	    expect(screen.getByRole("button", { name: "Sign in" })).toBeTruthy();
72	  });
73	
74	  test("a signed-in account shows its name and can sign out", async () => {
75	    fake.user = { id: "u1", name: "Keeper", email: "k@example.com", isAnonymous: false };
76	    render(<AccountPanel />);
77	    await waitFor(() => expect(screen.getByText("Signed in as Keeper")).toBeTruthy());
78	    await userEvent.click(screen.getByRole("button", { name: "Sign out" }));
79	    await waitFor(() => expect(screen.getByText("Offline")).toBeTruthy());
80	  });
81	
82	  test("a failed sign-out surfaces an error and keeps you signed in", async () => {
83	    fake.user = { id: "u1", name: "Keeper", email: "k@example.com", isAnonymous: false };
84	    fake.signOutRejects = true;
85	    render(<AccountPanel />);
86	    await waitFor(() => expect(screen.getByText("Signed in as Keeper")).toBeTruthy());
87	
88	    await userEvent.click(screen.getByRole("button", { name: "Sign out" }));
89	    // The rejection is caught: a visible error, still signed in, and the control is usable again.
90	    await waitFor(() => expect(screen.getByText(/Couldn't reach the server/)).toBeTruthy());
91	    expect(screen.getByText("Signed in as Keeper")).toBeTruthy();
92	    expect((screen.getByRole("button", { name: "Sign out" }) as HTMLButtonElement).disabled).toBe(false);
93	    fake.signOutRejects = false;
94	  });
95	});
