/** Rehearse migrations 0000→0003 on PGlite: seed a guest + account after 0002,
 *  run 0003, assert the guest cascade-deleted and the column dropped. */
import { PGlite } from "@electric-sql/pglite";
import { readFileSync } from "node:fs";

const dir = "/Users/hutusi/workspace/ai/david/monecraft/db/migrations";
const files = [
  "0000_online-foundation.sql",
  "0001_account-profiles.sql",
  "0002_profile-world-indexes.sql",
  "0003_retire-anonymous-guests.sql"
];

const db = new PGlite();
const apply = async (file: string) => {
  const sql = readFileSync(`${dir}/${file}`, "utf8");
  for (const statement of sql.split("--> statement-breakpoint")) {
    const trimmed = statement.trim();
    if (trimmed) await db.exec(trimmed);
  }
};

await apply(files[0]);
await apply(files[1]);
await apply(files[2]);

// Seed: one guest (world + membership + invite), one real account (world).
await db.exec(`
  INSERT INTO "user" (id, name, email, is_anonymous) VALUES
    ('guest-1', 'Guest', 'g@x', true),
    ('acct-1', 'Keeper', 'k@x', NULL);
  INSERT INTO worlds (id, owner_id, kind, name, seed, worldgen_version) VALUES
    ('gw', 'guest-1', 'mp', 'Guest Keep', 1, 11),
    ('aw', 'acct-1', 'mp', 'Account Keep', 2, 11);
  INSERT INTO world_members (world_id, user_id, role) VALUES
    ('gw', 'guest-1', 'owner'),
    ('aw', 'acct-1', 'owner'),
    ('aw', 'guest-1', 'member');
  INSERT INTO world_invites (id, world_id, token, created_by) VALUES
    ('inv-1', 'gw', 'tok-1', 'guest-1');
`);

await apply(files[3]);

const users = await db.query<{ id: string }>(`SELECT id FROM "user" ORDER BY id`);
const worlds = await db.query<{ id: string }>(`SELECT id FROM worlds ORDER BY id`);
const members = await db.query<{ user_id: string }>(`SELECT user_id FROM world_members`);
const invites = await db.query(`SELECT id FROM world_invites`);
const cols = await db.query<{ column_name: string }>(
  `SELECT column_name FROM information_schema.columns WHERE table_name = 'user'`
);

const assert = (cond: boolean, label: string) => {
  if (!cond) throw new Error(`FAILED: ${label}`);
  console.log(`ok: ${label}`);
};

assert(users.rows.map((r) => r.id).join(",") === "acct-1", "guest user deleted, account kept");
assert(worlds.rows.map((r) => r.id).join(",") === "aw", "guest world cascade-deleted");
assert(members.rows.every((r) => r.user_id === "acct-1") && members.rows.length === 1, "guest memberships gone");
assert(invites.rows.length === 0, "guest invite cascade-deleted");
assert(!cols.rows.some((r) => r.column_name === "is_anonymous"), "is_anonymous column dropped");
await db.close();
console.log("rehearsal passed");

